export default {
  props: {
    quotationSubAddDialogue: Boolean,
    selectedSubCategoryValue: Object,
    quotationType: String,
    selectedData: String
  },
  data() {
    return {
      price: "",
      quantity: "",
      gstTax: "",
      unit: "",
      unitItems: []
    };
  },
  watch: {
    quotationSubAddDialogue: {
      async handler() {
        if (this.quotationSubAddDialogue == true) {
          this.price = this.selectedSubCategoryValue.sub_category_price;
          this.unitItems = this.selectedSubCategoryValue.sub_category_unit_name;
        }
      },
      immediate: true
    }
  },
  methods: {
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.price = "";
      this.quantity = "";
      this.gstTax = "";
      this.unit = "";
    },
    async save_deatails() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        var SubData = {
          price: this.price,
          quantity: this.quantity,
          selectedValue: this.selectedSubCategoryValue,
          unit: this.unit
        };
        this.$emit("subInfo", SubData);
        this.price = "";
        this.quantity = "";
        this.gstTax = "";
        this.unit = "";
      }
    }
  }
};
